              "1. Máy xử lí thông tin.\nHoạt động 1: Thiết bị điều khiển được. (7’)\na. Mục tiêu:\n- HS mô tả được đầu vào, đầu ra và cách điều khiển một thiết bị điện tử gia dụng.\n🔹 Tích hợp AI (3.A1.1): Mở rộng khái niệm \"máy móc xử lí thông tin\": Trợ lí ảo (AI) cũng có thể \"nghe\" giọng nói, \"xử lí\" để tìm kiếm và trả lời, giúp em học tập.\nb. Cách tiến hành\n- GV yêu cầu HS trả lời câu hỏi: Hãy kể tên một số thiết bị điện trong gia đình có thể điều khiển được. Em hãy cho biết những thiết bị đó được điều khiển như thế nào?\n- GV chia lớp thành các nhóm nhỏ, yêu cầu HS thực hiện các nhiệm vụ sau:\n1) chọn một thiết bị:\n2) mô tả cách điều khiển thiết bị đó.\n3) xác định được thông tin và và kết quả xử lí.\n- GV mời đại diện 1-2 nhóm trình bày kết quả thảo luận. HS khác lắng nghe, nhận xét, bổ sung.\n- GV nhận xét, đánh giá.\n- GV mời 1 HS đứng dậy đọc to nội dung thông tin trong phần Hoạt động đọc SGK tr.10,11\n- GV kết luận: Có nhiều thiết bị tiếp nhận thông tin để quyết định hành động.\n- GV yêu cầu HS trả lời câu hỏi: 1. Minh chụp ảnh cánh đồng lúa bằng điện thoại thông minh. Khi đó, thông tin điện thoại thu nhận thuộc dạng gì? Sau khi xử lí, kết quả là gì?\n- GV mời đại diện 1-2 HS trả lời. HS khác lắng nghe, nhận xét.\n- GV yêu cầu HS thảo luận nhóm ba và trả lời câu hỏi: 2. Em hãy nêu ví dụ về một hoạt động của chiếc quạt điện có điều khiển từ xa. Trong hoạt động đó thông tin tiếp nhận là gì? Chiếc quạt quyết định hành động thế nào?\n- GV mời đại diện 1-2 HS trả lời. HS lắng nghe, nhận xét, bổ sung.\n- GV nhận xét và kết luận.\n🔹 Tích hợp AI: GV dùng điện thoại mở Google Assistant (hoặc Siri), cho 1 HS hỏi một phép toán đơn giản (VD: 5 cộng 7 bằng mấy) để cả lớp thấy AI tiếp nhận thông tin (nghe), xử lí và phản hồi.\n- GV hỏi: Trợ lí ảo đã tiếp nhận thông tin gì và kết quả xử lí ra sao?",
              "- HS trả lời:\n+ Một số thiết bị trong gia đình có thể điều khiển được: tivi, máy giặt, điều hoà,...\n+ Những thiết bị đó được điều khiển bằng cách sử dụng điều khiển (tivi, điều hoà,...) hoặc nút bấm có sẵn trên thiết bị (máy giặt,...).\n- HS thảo luận nhóm, trình bày và nghe GV nhận xét.\n- HS đọc thầm theo bạn.\n- HS lắng nghe và ghi nhớ.\n- HS trả lời: Minh chụp ảnh cánh đồng lúa bằng điện thoại thông minh.\n+Ống kính máy ảnh của điện thoại sẽ thu nhận được hình ảnh đồng lúa ngoài thực tế.\n+ Sau khi xử lí, điện thoại sẽ cho kết quả là một tệp hình ảnh mà ta có thể nhìn lại nó trên màn hình, lưu trữ trong bộ nhớ và truyền gửi tới những thiết bị khác.\n- HS lắng nghe, tiếp thu.\n- HS thảo luận nhóm và trả lời:\nChiếc quạt điện tiếp nhận thông tin từ điều khiển từ xa để thực hiện yêu cầu của người dùng. Các lựa chọn bật, tắt, tăng, giảm tốc độ, chuyển hướng gió cũng là những mệnh lệnh được người sử dụng chuyển cho quạt (thông tin tiếp nhận) để nó thực hiện (quyết định hành động).\nVí dụ về một hoạt động của chiếc quạt máy có điều khiển từ xa: khi bấm nút nguồn (nút đỏ) để khởi động quạt, cánh quạt đang đứng im bắt đầu chuyển động.\n+ Thông tin tiếp nhận: bấm nút nguồn để khởi động quạt.\n+ Chiếc quạt quyết định hành động bằng cách: cánh quạt đang đứng im bắt đầu chuyển động.\n- HS lắng nghe và ghi nhớ.\n🔹 HS quan sát GV trải nghiệm công cụ AI.\n- HS trả lời: + Một số thiết bị trong gia đình...\n- HS lắng nghe và ghi nhớ\n- HS trả lời: Trợ lí ảo tiếp nhận câu hỏi phép toán bằng giọng nói và kết quả xử lí là đọc ra đáp án chính xác."
