              "BT2.\n+ Thông tin bếp từ tiếp nhận được là mệnh lệnh tăng nhiệt độ.\n+ Nó quyết định duy trì cấp điện để tăng nhiệt của bếp đến khi bếp đặt nhiệt độ được chỉ thị."
