              "5.CỦNG CỐ, DẶN DÒ (3 phút)\nCủng cố:\n- GV hỏi – HS trả lời:\n+ Vì sao máy tính giúp con người xử lí thông tin nhanh và chính xác?\nDặn dò :\n- Quan sát xung quanh và ghi lại 3 việc mà em thấy có sử dụng máy tính để xử lí thông tin.\n- Chuẩn bị bài tiếp theo"
