              "- GV chia nhóm lớp thành các nhóm nhỏ ( 3 – 4 HS).\n- GV yêu cầu HS thảo luận nhóm và trả lời câu hỏi: Tư thế ngồi khi sử dụng máy tính của bạn nào sau đây chưa đúng? Vì sao?\n- GV mời đại diện 1-2 nhóm trình bày kết quả thảo luận. HS khác lắng nghe, nhận xét, bổ sung.\n- GV nhận xét, đánh giá.\n- GV yêu cầu HS trả lời câu hỏi: Nếu ngồi sai tư thế thường xuyên có ảnh hưởng đến sức khỏe không?\n- GV hướng dẫn HS tự đọc thông tin trong phần Hoạt động đọc SGK tr.19 và giảng cho HS hiểu được:\n+ Khoảng cách từ mắt đến màn hình: 50 – 80cm.\n+ Lưng thẳng, vai thả lòng.\n+ Tay: để ngang bàn phím\n+ Chân: Hai bàn chân chạm đất\n+ Ngồi đúng tư thế giúp em tránh được các bệnh về cột sống và mắt.\n- GV yêu cầu HS thực hành tư thế ngồi khi sử dụng máy tính đúng cách.\n- GV yêu cầu HS trả lời câu hỏi: Vị trí đèn trong lớp học đã được bố trí hợp lí chưa? Ánh sáng của đèn trong lớp học có chiếu thẳng vào màn hình mắt hay không?\n- GV chốt lại câu trả lời:\n+ Không nên sử dụng máy tính thời gian dài, nghỉ ngơi và thư giãn sau khoảng 30 phút sử dụng máy tính.\n+ Đặt máy tính ở vị trí sao cho ánh sáng không trực tiếp chiếu vào màn hình mặc mắt.\n- GV cần nhấn mạnh: Khi ngồi làm việc với máy tính cũng như khi ngồi học bài, em cần ngồi đúng tư thế để phòng tránh các bệnh về mắt, cột sống. Tư thế ngồi làm việc với máy tính đúng giúp em làm việc, học tập hiệu quả.\n- GV kết luận: Khi sử dụng máy tính cần ngồi đúng tư thế và giữ đúng khoảng cách để bảo vệ sức khỏe.\n- GV yêu cầu HS trả lời câu hỏi:\n1. Tư thế ngồi khi sử dụng máy tính đúng sẽ giúp em tránh nguy cơ mắc những bệnh nào sau đây?\nA. Vẹo cột sống\nB. Đau tai\nC. Cận thị\nD. Đau chân\n2. Tư thế nào sau đây là đúng khi sử dụng máy tính?\n🔹 Định hướng Năng lực số (4.3.CB1a): GV cho xem 2 bức ảnh: Một bạn ngồi thẳng lưng, phòng đủ sáng và một bạn ngồi gập người, trong bóng tối.\n- Hỏi: \"Nếu ngồi như bạn thứ 2 trong thời gian dài, cơ thể em sẽ cảm thấy thế nào?\"\nChốt: Để bảo vệ sức khỏe tinh thần và thể chất, em cần ngồi đúng tư thế.",
              "- HS ghi vào bảng nhóm (giấy A2, A3) câu trả lời của nhóm mình:\n+ HS ngồi đúng là Hình 18c.\n+ Hình 18a: HS ngồi sai vì lưng chưa thẳng, tay để với ngang vai, khoảng cách giữa ghế và mặt bàn chưa phù hợp.\n+ Hình 18b: HS ngồi sai vì lưng chưa thẳng, khoảng cách của mắt đến màn hình quá gần, khoảng cách giữa ghế và mặt bàn chưa phù hợp.\n- HS lắng nghe và tiếp thu.\n- HS trả lời câu hỏi: Nếu ngồi học sai tư thế thì sẽ ảnh hưởng không tốt đến sức khỏe và có thể mắc các bệnh về cột sống và mắt.\n- HS lắng nghe và ghi nhớ.\n- HS thực hành theo hướng dẫn của GV.\n- HS trả lời.\n- HS lắng nghe và ghi nhớ.\n- HS lắng nghe\n- HS lắng nghe và ghi nhớ.\n- HS trả lời:\n1. Đáp án A và C\n2. Đáp án C\n- HS lắng nghe và tiếp thu\n- HS quan sát, trả lời (Đau cổ, mỏi mắt, buồn bực...)"
