              "- GV chia HS thành 4 nhóm.\n- GV yêu cầu các nhóm đọc câu chuyện của gia đình bạn Khoa, quan sát hình SGK tr.30, 31 và cho biết:\n+ Những ai trong gia đình bạn Khoa sử dụng internet?\n+ Gia đình bạn Khoa sử dụng Internet vào việc gì?\n- GV mời đại diện 1-2 nhóm trình bày kết quả thảo luận trước lớp. Các nhóm khác lắng nghe, nhận xét, bổ sung.\n- GV nhận xét, đánh giá.\n- GV kết luận: Khi truy cập Internet, em có thể xem tin tức từ các chương trình giải trí như phim hoạt hình, phim truyện, ca nhạc,....\n- GV yêu cầu HS thảo luận nhóm đôi và trả lời câu hỏi: Em có thể xem tin tức hay chương trình giải trí nào dưới đây trên Internet?\nA. Lịch thi đấu đá bóng.\nB. Phim hoạt hình dành cho thiếu nhi.\nC. Video giới thiệu các danh lam thắng cảnh, điểm du lịch.\nD. Cả A, B, C đều đúng.\n- GV mời đại diện 1-2 HS chọn đáp án đúng. HS khác lắng nghe, nhận xét.\n- GV mở rộng kiến thức cho HS và yêu cầu HS trả lời câu hỏi:\n+ Khi xem lịch thi đấu bóng đá trên Internet, em thu thập được thông tin là gì?\n+ Phim hoạt hình trên Internet là chương trình giải trí hay là một trang tin tức?\n+ Video trên internet giới thiệu các danh lam thắng cảnh, điểm du lịch nổi tiếng là chương trình giải trí hay chương trình cung cấp tin tức?\n- GV mời đại diện 1-2 HS trả lời. HS lắng nghe, nhận xét, bổ sung.\n- GV yêu cầu HS kể thêm ví dụ về tin tức và chương trình giải trí mà em đã xem được khi truy cập Internet.",
