              "- HS chia nhóm.\n- HS quan sát Hình 44,45 và thảo luận nhóm.\n- HS trả lời:\n+ Các con vật sống dưới nước: 1. Cá mập, 2. Tôm, 6. Cá hề.\n+ Các con vật sống trên cạn: 3. Mèo, 4. Ngựa, 5. Chó, 7. Voi, 8. Sư tử.\n+ Thẻ con voi nằm trong nhóm con vật sống trên cạn.\n- HS lắng nghe và bổ sung\n- HS lắng nghe và tiếp thu\n- HS trả lời:\n+ Các con vật sống trong rừng: 7. Voi, 8. Sư tử.\n+ Các con vật nuôi trong gia đình: 3. Mèo, 4. Ngựa, 5. Chó\n+ Thẻ con voi nằm trong nhóm con vật sống trong rừng.\n- HS lắng nghe, tiếp thu.\n- HS trả lời.\n- HS lắng nghe và bổ sung\n- HS lắng nghe và ghi nhớ\n- HS trả lời:\n+ Truyện, thơ: Thơ học trò, truyện cười, Dế mèn phiêu lưu ký truyện tranh, truyện cổ tích, hoàng tử bé.\n+ Sách giáo khoa: Tiếng Anh 3, TIếng Việt 3, Âm nhạc 3, Tự nhiên và Xã hội 3, Toán 3.\n+ Vở viết.\n- HS lắng nghe và bổ sung\n- HS lắng nghe và ghi nhớ.\n- HS trả lời:\n+ Nhóm 1: Vợt cầu lông\n+ Nhóm 2: Xe đạp\n+ Nhóm 3: Tủ quần áo.\n- HS lắng nghe, tiếp thu.\n- HS lắng nghe và ghi nhớ"
