              "- HS thực hành theo hướng dẫn của GV.\n- HS thực hành theo nhiều cách khác nhau.\n- HS trả lời:\n+ Dải lệnh Home có các tùy chọn phông chữ và đoạn văn cũng như các chức năng cần để thêm và sắp xếp các trang chiếu.\n+ Dải lệnh Insert: để thêm thứ gì đó vào trang chiếu. Những đối tượng có thể thêm là ảnh, hình dạng, biểu đồ, hộp văn bản, video,…\n+ Dải lệnh Design: để thêm chủ đề hoặc bảng phối màu hoặc định dạng nền của trang chiếu.\n- HS lắng nghe và đọc nhẩm theo.\n- HS lắng nghe và ghi nhớ.\n- HS thực hành."
