              "NHIỆM VỤ 2: Nhập văn bản, tạo trang mới và thêm hình ảnh vào trang trình chiếu về chủ đề các loại hoa. (10’)\n- GV hướng dẫn HS làm từng bước theo hướng dẫn trong SGK – tr51-53.\n- GV cài sẵn một số hình ảnh về các loài hoa trong máy tính.\n- GV quan sát HS luyện tập và nhắc nhở các em thực hiện các tư thế và thao tác cho đúng.\n- Nếu HS thực hiện thao tác sai, GV hướng dẫn HS nháy nút lệnh quay lại hoặc nhấn tổ hợp phím Ctrl + Z.\n- Nếu HS chèn sai ảnh, GV hướng dẫn thêm cho HS thao tác xóa ảnh: Chọn ảnh → nhấn phím Delete trên bàn phím.\n- GV khuyến khích HS thực hành và tìm hiểu 1,2 lần và chữa lỗi sai (nếu có).",
              "- HS đọc các bước thực hành trong SGK.\n- HS thực hành.\n- HS lắng nghe và tiếp thu."
