              "- GV quan sát, bao quát phòng thi; nhắc nhở học sinh tập trung làm bài.\n- GV hỗ trợ kịp thời các sự cố kỹ thuật phần cứng/máy tính (nếu có), đảm bảo tính công bằng và thời gian làm bài của học sinh.\n- Đối với học sinh khuyết tật học hòa nhập: GV hỗ trợ theo mức độ giảm tải quy định, động viên học sinh hoàn thành các câu hỏi nhận biết cơ bản.",
              "- HS tập trung làm bài kiểm tra:\n  + Phần Lý thuyết: Đọc kĩ câu hỏi, lựa chọn đáp án chính xác.\n  + Phần Thực hành: Khởi động phần mềm, thực hiện đúng các thao tác theo yêu cầu của đề bài và lưu tệp bài làm cẩn thận."
